# Hand-written (not autogenerated as-is) to preserve existing farm/planting
# data: adds the new fields/tables first, backfills one allocation row per
# existing purchase from its old farm/planting/pest_incident values, and only
# then drops those old fields — instead of Django's naive column drop, which
# would silently lose which farm/planting each existing record belonged to.

import django.db.models.deletion
import simple_history.models
from django.conf import settings
from django.db import migrations, models


def migrate_allocations(apps, schema_editor):
    SeedlingPurchase = apps.get_model("crops", "SeedlingPurchase")
    SeedlingPurchaseAllocation = apps.get_model("crops", "SeedlingPurchaseAllocation")
    SoilTreatment = apps.get_model("crops", "SoilTreatment")
    SoilTreatmentAllocation = apps.get_model("crops", "SoilTreatmentAllocation")
    PesticideApplication = apps.get_model("crops", "PesticideApplication")
    PesticideApplicationAllocation = apps.get_model("crops", "PesticideApplicationAllocation")

    for row in SeedlingPurchase.objects.all():
        SeedlingPurchaseAllocation.objects.create(
            purchase=row, farm_id=row.farm_id, quantity=row.quantity, planting_id=row.planting_id
        )

    for row in SoilTreatment.objects.all():
        SoilTreatmentAllocation.objects.create(
            purchase=row, farm_id=row.farm_id, quantity=row.quantity, planting_id=row.planting_id
        )

    for row in PesticideApplication.objects.select_related("planting").all():
        PesticideApplicationAllocation.objects.create(
            purchase=row,
            farm_id=row.planting.farm_id,
            quantity=row.quantity,
            planting_id=row.planting_id,
            pest_incident_id=row.pest_incident_id,
        )


def noop_reverse(apps, schema_editor):
    pass


